$_MODULE['<{layerslider}prestashop>_4cae6acadf866d95afb764b4e6545be5'] = 'Podgląd Youtube'; // Youtube preview
$_MODULE['<{layerslider}prestashop>_a5ade6e166855925e2f6ea1f1cd50a8c'] = 'Jakość automatycznie pobieranego obrazu podglądu dla filmów z YouTube, gdy nie ustawisz własnego. Pamiętaj, że niektóre filmy nie mają podglądu w jakości HD i może być konieczne wybranie niższej jakości.'; // The automatically fetched preview image quaility for YouTube videos when you do not set your own. Please note, some videos do not have HD previews, and you may need to choose a lower quaility.
$_MODULE['<{layerslider}prestashop>_155a657eee2a2e2b07c3a47b93c478f6'] = 'Maksymalna jakość'; // Maximum quality
$_MODULE['<{layerslider}prestashop>_b8924eb7fe4c3fb0219f7709d999acb6'] = 'Wysoka jakość'; // High quality
$_MODULE['<{layerslider}prestashop>_31186f925fe95370a86649eb2b2e00c3'] = 'Średnia jakość'; // Medium quality
$_MODULE['<{layerslider}prestashop>_722597fc491a17f65a7b2c9db01ec6b1'] = 'Domyślna jakość'; // Default quality
$_MODULE['<{layerslider}prestashop>_be0233bf54a7d9579cbf0356bce96b17'] = 'Używaj względnych adresów URL'; // Use relative URLs
$_MODULE['<{layerslider}prestashop>_ba82cbe6dc7a81f3d77fabb6d414c0ee'] = 'Używaj względnych adresów URL dla lokalnych obrazów. To ustawienie może być ważne podczas przenoszenia instalacji PS.'; // Use relative URLs for local images. This setting could be important when moving your PS installation.
$_MODULE['<{layerslider}prestashop>_c878cdf0cb53e7dbeb791eab13b84146'] = 'Zezwalaj na ponowne uruchamianie slajdów przy zmianie rozmiaru'; // Allow restarting slides on resize
$_MODULE['<{layerslider}prestashop>_0296ddaa31acdc8e379a3de8412aff9a'] = 'Niektóre opcje transformacji i przejść nie mogą być aktualizowane na bieżąco, gdy zmienia się rozmiar przeglądarki lub orientacja urządzenia. Włączenie tej opcji sprawi, że suwak automatycznie wykryje takie sytuacje i uruchomi się ponownie, aby zachować swój wygląd.'; // Certain transformation and transition options cannot be updated on the fly when the browser size or device orientation changes. By enabling this option, the slider will automatically detect such situations and will restart the itself to preserve its appearance.
$_MODULE['<{layerslider}prestashop>_d9f1451d7e147a9d76732b903c85fd98'] = 'Użyj atrybutu srcset'; // Use srcset attribute
$_MODULE['<{layerslider}prestashop>_d962a6678a6f57c0697bdba39433e0d7'] = 'Atrybut srcset pozwala na ładowanie dynamicznie skalowanych obrazów w zależności od rozdzielczości ekranu. Może to zaoszczędzić przepustowość i pozwolić na używanie obrazów gotowych na ekrany retina na urządzeniach o wysokiej rozdzielczości. W rzadkich przypadkach ta opcja może powodować rozmyte obrazy.'; // The srcset attribute allows loading dynamically scaled images based on screen resolution. It can save bandwidth and allow using retina-ready images on high resolution devices. In some rare edge cases, this option might cause blurry images.
$_MODULE['<{layerslider}prestashop>_806790e901a729799c42f26b23c5470f'] = 'Ulepszone leniwe ładowanie'; // Enhanced lazy load
$_MODULE['<{layerslider}prestashop>_bb477d8d7ee0d5561c80c51482d44904'] = 'Domyślne zachowanie leniwego ładowania stanowi kompromis w celu zapewnienia maksymalnej kompatybilności, oferując jednocześnie rozwiązanie, które działa idealnie w prawie wszystkich przypadkach. Jednakże, pozostawiając atrybut ’src’ obrazu nietkniętym, istnieje niewielka szansa, że przeglądarka może zacząć pobierać niektóre zasoby na ułamek sekundy, zanim Creative Slider je anuluje. Włączenie tej opcji wyeliminuje wszelkie szanse na generowanie nawet minimalnej ilości niechcianego ruchu, ale może również powodować problemy z indeksowaniem przez wyszukiwarki oraz z innymi motywami/modułami.'; // The default lazy loading behavior makes a compromise to ensure maximum compatibility while offering a solution that works ideally in almost all cases. However, by leaving the image ’src’ attribute untouched, there is a slight chance that the browser might start downloading some assets for a split second before Creative Slider cancels them. Enabling this option will eliminate any chance of generating even a minuscule amount of unwanted traffic, but it can also cause issues for search engine indexing and other themes/modules.
$_MODULE['<{layerslider}prestashop>_451af3f11142c7626d839eb7674d3e0a'] = 'Preferuj tryb mieszania'; // Prefer Blend Mode
$_MODULE['<{layerslider}prestashop>_6da524b45307ee7baa37799db0cd4796'] = 'Włącz tę opcję, aby uniknąć problemów z trybem mieszania podczas przejść slajdów. Ze względu na ograniczenia techniczne, spowoduje to również przycięcie przejść slajdów, niezależnie od ustawień.'; // Enable this option to avoid blend mode issues with slide transitions. Due to technical limitations, this will also clip your slide transitions regardless of your settings.
$_MODULE['<{layerslider}prestashop>_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Włączone'; // Enabled
$_MODULE['<{layerslider}prestashop>_5e1575919121f7253b56bb39b99e1042'] = 'TwojeLogo'; // YourLogo
$_MODULE['<{layerslider}prestashop>_367a210257e2ea49914c4a695f8abf70'] = 'Stała warstwa obrazu może być wyświetlana nad suwakiem i pozostaje nieruchoma przez cały czas jego trwania. Może być używana do wyświetlania logo lub znaków wodnych.'; // A fixed image layer can be shown above the slider that remains still throughout the whole slider. Can be used to display logos or watermarks.
$_MODULE['<{layerslider}prestashop>_77c34b7517dd216292658ee3b420dd1f'] = 'Styl TwojegoLogo'; // YourLogo style
$_MODULE['<{layerslider}prestashop>_355a12e47302b7e2627dc90d1c0e79c6'] = 'Właściwości CSS do kontrolowania umiejscowienia i wyglądu obrazu.'; // CSS properties to control the image placement and appearance.
$_MODULE['<{layerslider}prestashop>_1cfb56506d3621c27196a6aa02a23c39'] = 'Link TwojegoLogo'; // YourLogo link
$_MODULE['<{layerslider}prestashop>_7966bee26ee8f49f0c5693a3b25a3461'] = 'Wprowadź adres URL, aby połączyć obraz TwojegoLogo.'; // Enter a URL to link the YourLogo image.
