$_MODULE['<{layerslider}prestashop>_13eac5a039bc8041315fe1165a245a98'] = 'Rozmiar obrazu tła slajdu. Pozostaw tę opcję na „dziedzicz”, jeśli chcesz ustawić ją globalnie w Ustawieniach suwaka.'; // The size of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
