$_MODULE['<{layerslider}prestashop>_25824be059f35ecadb2d38a895f7e710'] = 'Pozycja obrazu tła slajdu. Pozostaw tę opcję na „dziedzicz”, jeśli chcesz ustawić ją globalnie w Ustawieniach suwaka.'; // The position of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_cb5feb1b7314637725a2e73bdc9f7295'] = 'Kolor'; // Color
$_MODULE['<{layerslider}prestashop>_9880a2532d7550cb4bef6c24ce2275f3'] = 'Kolor tła slajdu. Możesz używać nazw kolorów, wartości szesnastkowych, RGB lub RGBA.'; // The slide background color. You can use color names, hexadecimal, RGB or RGBA values.
$_MODULE['<{layerslider}prestashop>_9d8cfafeba857023956c26437b6570fc'] = 'Ustaw miniaturę slajdu'; // Set a slide thumbnail
$_MODULE['<{layerslider}prestashop>_b95232d8c69a9f62cd6dab61887acf0f'] = 'Obraz miniatury tego slajdu. Kliknij na obraz, aby otworzyć Menedżer obrazów i wybrać lub przesłać obraz. Jeśli pozostawisz to pole puste, zostanie użyty obraz slajdu.'; // The thumbnail image of this slide. Click on the image to open the Image Manager to choose or upload an image. If you leave this field empty, the slide image will be used.
$_MODULE['<{layerslider}prestashop>_e02d2ae03de9d493df2b6b2d2813d302'] = 'Czas trwania'; // Duration
$_MODULE['<{layerslider}prestashop>_b0c71ca949422ff07096787e513bf3dc'] = 'Tutaj możesz ustawić interwał czasowy między zmianami slajdów; ten slajd będzie widoczny przez określony tutaj czas. Wartość jest w milisekundach, więc wartość 1000 oznacza 1 sekundę. Proszę nie używać wartości 0 ani bardzo niskich.'; // Here you can set the time interval between slide changes, this slide will stay visible for the time specified here. This value is in millisecs, so the value 1000 means 1 second. Please don't use 0 or very low values.
$_MODULE['<{layerslider}prestashop>_4357cfb0b7acc1db400c94094794ae17'] = 'Nasze predefiniowane przejścia slajdów zostały stworzone ze szczególną starannością, aby pasowały do większości przypadków użycia. Jeśli jednak chcesz zwiększyć lub zmniejszyć prędkość tych przejść, możesz nadpisać ich czas, podając własną długość przejścia w milisekundach (1 sekunda = 1000 milisekund).'; // We've made our pre-defined slide transitions with special care to fit in most use cases. However, if you would like to increase or decrease the speed of these transitions, you can override their timing here by providing your own transition length in milliseconds. (1 second = 1000 milliseconds)
$_MODULE['<{layerslider}prestashop>_38912a644194123a9ee9d01e126fcfae'] = 'własny czas trwania'; // custom duration
$_MODULE['<{layerslider}prestashop>_1605a4f4a4e45503d3ac914de9fba80a'] = 'Przesunięcie czasowe'; // Time Shift
$_MODULE['<{layerslider}prestashop>_6d106138f5fadb601a337fca4d4b7a2e'] = 'Możesz przesunąć punkt początkowy osi czasu animacji slajdu, aby warstwy mogły animować się wcześniej po zmianie slajdu. Ta wartość jest w milisekundach. Sekunda to 1000 milisekund. Możesz używać tylko wartości ujemnych.'; // You can shift the starting point of the slide animation timeline, so layers can animate in an earlier time after a slide change. This value is in milliseconds. A second is 1000 milliseconds. You can only use a negative value.
$_MODULE['<{layerslider}prestashop>_e1f70f4a4265cb51c1b219aa60eaa441'] = 'Wprowadź URL'; // Enter URL
$_MODULE['<{layerslider}prestashop>_cfdb83fef5ccd56abb3592f98391b355'] = 'Jeśli chcesz połączyć cały slajd, wpisz tutaj adres URL. Możesz wybrać jedną z predefiniowanych opcji z listy rozwijanej, klikając w to pole. Możesz również wpisać znak krzyżyka, a następnie numer, aby połączyć tę warstwę z innym slajdem. Przykład: #3 - to przełączy na trzeci slajd.'; // If you want to link the whole slide, type the URL here. You can choose one of the pre-defined options from the dropdown list when you click into this field. You can also type a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_1f7412ef1f7fdba3cc269af9a0b7a40c'] = 'Cel linku'; // Link Target
$_MODULE['<{layerslider}prestashop>_e82688575274fd1ba522f5044431cc93'] = 'Przewiń do elementu (Wprowadź selektor)'; // Scroll to element (Enter selector)
$_MODULE['<{layerslider}prestashop>_1fc71d8275be86e2787bc4a8f0d62c84'] = 'Wybierz, czy link slajdu ma być nad czy pod warstwami. Ta druga opcja sprawia, że link jest klikalny tylko w pustych miejscach, gdzie widoczne jest tło slajdu, i pozwala na niezależne łączenie zarówno slajdów, jak i warstw.'; // Choose whether the slide link should be on top or underneath your layers. The later option makes the link clickable only at empty spaces where the slide background is visible, and enables you to link both slides and layers independently from each other.
$_MODULE['<{layerslider}prestashop>_7e04fe64ab136e31d62fcc6ea113f1ca'] = 'Nad warstwami'; // On top of layers
$_MODULE['<{layerslider}prestashop>_d722a275a3f48eb46d892c9df863e1af'] = 'Pod warstwami'; // Underneath layers
$_MODULE['<{layerslider}prestashop>_739cea2b85156183f917f2ccaa10a50c'] = '#ID'; // #ID
$_MODULE['<{layerslider}prestashop>_06f695600f91bfbd579d9d8f5a0147bd'] = 'Możesz zastosować atrybut ID na elemencie HTML tego slajdu, aby pracować z nim w niestandardowym kodzie CSS lub Javascript.'; // You can apply an ID attribute on the HTML element of this slide to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_550dc007dba485adc22eddfe0af40a81'] = 'Głęboki link'; // Deeplink
$_MODULE['<{layerslider}prestashop>_070cb374111546db9ae4642406963ebd'] = 'Możesz określić alias slajdu, którego możesz używać w adresach URL ze znakiem krzyżyka, dzięki czemu Creative Slider rozpocznie od odpowiedniego slajdu.'; // You can specify a slide alias name which you can use in your URLs with a hash mark, so Creative Slider will start with the correspondig slide.
$_MODULE['<{layerslider}prestashop>_436e4906cf91bb911a38eb161e858a69'] = 'Globalne najechanie'; // Global Hover
$_MODULE['<{layerslider}prestashop>_f22bc2f96ed30d26a29060598c44c2fa'] = 'Włączenie tej opcji spowoduje, że wszystkie warstwy uruchomią swoje przejścia po najechaniu myszą w tym samym czasie, gdy najedziesz kursorem na suwak. Jest to przydatne do tworzenia spektakularnych efektów, które obejmują wiele przejść warstw i aktywują się po najechaniu na suwak, a nie na poszczególne warstwy.'; // By turning this option on, all layers will trigger their Hover Transitions at the same time when you hover over the slider with your mouse cursor. It’s useful to create spectacular effects that involve multiple layer transitions and activate on hovering over the slider instead of individual layers.
$_MODULE['<{layerslider}prestashop>_7acdf85c69cc3c5305456a293524386e'] = 'Ukryty'; // Hidden
$_MODULE['<{layerslider}prestashop>_a494a9272210a3aa3682f9fa8b6ad9fc'] = 'Jeśli nie chcesz używać tego slajdu na stronie głównej, ale chcesz go zachować, możesz go ukryć za pomocą tego przełącznika.'; // If you don't want to use this slide in your front-page, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_d33fd48027b557f5bcb3f15a238d7537'] = 'Przepełnienie warstw'; // Overflow layers
$_MODULE['<{layerslider}prestashop>_5bbae9c02b64de11da4d22707a297710'] = 'Domyślnie suwak przycina warstwy wychodzące poza jego granice. Włącz tę opcję, aby zezwolić na przepełnienie zawartości.'; // By default the slider clips the layers outside of its bounds. Enable this option to allow overflowing content.
$_MODULE['<{layerslider}prestashop>_57ffe7327fb6fb004c59466a978c4100'] = 'Rozpocznij od'; // Start on
$_MODULE['<{layerslider}prestashop>_6ba9104be4da1fea318c02faca91dad6'] = 'Zaplanowany slajd będzie widoczny dla odwiedzających tylko w określonym przez Ciebie okresie czasu.<br>Używamy międzynarodowego formatu daty i godziny, aby uniknąć niejednoznaczności.'; // Scheduled slide will only be visible to your visitors between the time period you set here.<br>We're using international date and time format to avoid ambiguity.
$_MODULE['<{layerslider}prestashop>_6ea6d7b483daeb9be3acaad212b04181'] = 'Zakończ na'; // Stop on
$_MODULE['<{layerslider}prestashop>_b78a3223503896721cca1303f776159b'] = 'Tytuł'; // Title
$_MODULE['<{layerslider}prestashop>_a2e92861b757ab878312dd57993d60cf'] = 'Alt'; // Alt
$_MODULE['<{layerslider}prestashop>_f17b29e841d3183298a453dc423242a0'] = 'Nazwij lub opisz obraz slajdu, aby wyszukiwarki i oprogramowanie VoiceOver mogły go prawidłowo zidentyfikować.'; // Name or describe your slide image, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_4252b72e6ebcd4d4b4c2e46a786f03d2'] = 'Powiększenie'; // Zoom
$_MODULE['<{layerslider}prestashop>_f5ca4abce85e2dddb0342d0bae3a7270'] = 'Powiększ'; // Zoom In
$_MODULE['<{layerslider}prestashop>_30850b501f98539b1aabaa29fabe41ef'] = 'Pomniejsz'; // Zoom Out
$_MODULE['<{layerslider}prestashop>_8d2de5368588552fbae54044ac5c7b3d'] = 'Obrót'; // Rotate
$_MODULE['<{layerslider}prestashop>_8aa2fa2e684ba408f551f3504c47427e'] = 'Wartość obrotu (jeśli jest) w stopniach używana w efekcie Kena Burnsa. Wartości ujemne są dozwolone dla obrotu w kierunku przeciwnym do ruchu wskazówek zegara.'; // The amount of rotation (if any) in degrees used in the Ken Burns effect. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_85a7cd587d6142dbfc1a4de05af7b75d'] = 'Skala'; // Scale
$_MODULE['<{layerslider}prestashop>_2ed8e1d37be922f23b2713c3e69a85ae'] = 'Zwiększ lub zmniejsz rozmiar obrazu tła slajdu w efekcie Kena Burnsa. Wartość domyślna to 1, wartość 2 podwoi obraz, a 0,5 zmniejszy go o połowę. Wartości ujemne odwrócą obraz.'; // Increase or decrease the size of the slide background image in the Ken Burns effect. The default value is 1, the value 2 will double the image, while 0.5 results half the size. Negative values will flip the image.
$_MODULE['<{layerslider}prestashop>_a1fa27779242b4902f7ae3bdd5c6d508'] = 'Typ'; // Type
$_MODULE['<{layerslider}prestashop>_4a2d97fd5296d09fea3cbe45d107a7b3'] = 'Wartość domyślna dla warstw paralaksy na tym slajdzie, którą odziedziczą, chyba że ustawisz inaczej na poszczególnych warstwach.'; // The default value for parallax layers on this slide, which they will inherit, unless you set it otherwise on the affected layers.
$_MODULE['<{layerslider}prestashop>_8c94134f25efe7680f9743b2774e8e1f'] = '2D'; // 2D
$_MODULE['<{layerslider}prestashop>_76aa96369abbba52e621bfa83da8e64f'] = '3D'; // 3D
$_MODULE['<{layerslider}prestashop>_a4ecfc70574394990cf17bd83df499f7'] = 'Zdarzenie'; // Event
$_MODULE['<{layerslider}prestashop>_87932092d26d18e63889036bbf70518e'] = 'Możesz wywołać efekt paralaksy, przewijając stronę, przesuwając kursor myszy lub przechylając urządzenie mobilne. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_58af070b9f7f3dc090af0ece708e8869'] = 'Kursor lub Przechylenie'; // Cursor or Tilt
$_MODULE['<{layerslider}prestashop>_61ca8fa7a7c8b4699523bc8773c306d0'] = 'Osie'; // Axes
$_MODULE['<{layerslider}prestashop>_fc888362a84b5b975136bbca8e1fc5c6'] = 'Wybierz, na których osiach mają poruszać się warstwy paralaksy. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // Choose on which axes parallax layers should move. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_6adf97f83acf6453d4a6a4b1070f3754'] = 'Brak'; // None
$_MODULE['<{layerslider}prestashop>_2c452204ed58a6f4a3bcda80344b338a'] = 'Obie osie'; // Both axes
$_MODULE['<{layerslider}prestashop>_ad09aaae9c9ffe403ffdb2a6568f5a36'] = 'Tylko poziomo'; // Horizontal only
$_MODULE['<{layerslider}prestashop>_354908b89248f3dcbab970b32860a331'] = 'Tylko pionowo'; // Vertical only
$_MODULE['<{layerslider}prestashop>_8b622b0a6ecf4e0116eaf248876f8700'] = 'Początek transformacji'; // Transform Origin
$_MODULE['<{layerslider}prestashop>_e5a904ff73268b65730e4fb8b6127bf1'] = 'Ustawia punkt na płótnie, od którego obliczane są transformacje. Na przykład warstwa może obracać się wokół swojego środka lub całkowicie niestandardowego punktu, takiego jak jeden z jej rogów. Trzy wartości reprezentują osie X, Y i Z w przestrzeni 3D. Oprócz wartości w pikselach i procentach, można również użyć następujących stałych: top, right, bottom, left, center.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center.
$_MODULE['<{layerslider}prestashop>_97289d779de759c4fe3a0ef9d3a4ff3d'] = 'Czas trwania ruchu'; // Move duration
$_MODULE['<{layerslider}prestashop>_ef82e470cae5696da7dc47e9a50fa8f7'] = 'Kontroluje prędkość animacji warstw podczas przesuwania kursora myszy lub przechylania urządzenia mobilnego. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0bdd8970e06688e4a6ad694b8ed7b9f7'] = 'Czas trwania opuszczania'; // Leave duration
$_MODULE['<{layerslider}prestashop>_9aa9b8945ad7ff74e04fb53dbbe3d1f2'] = 'Kontroluje, jak szybko warstwy wracają do swojej pierwotnej pozycji po opuszczeniu kursora myszy z obszaru suwaka paralaksy. Wartość jest w milisekundach. 1 sekunda = 1000 milisekund. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // Controls how quickly your layers revert to their original position when you move your mouse cursor outside of a parallax slider. This value is in milliseconds. 1 second = 1000 milliseconds. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0aa6f4210bf373c95eda00232e93cd98'] = 'Odległość'; // Distance
$_MODULE['<{layerslider}prestashop>_396950a091a406fcd6f9f4cc75927536'] = 'Zwiększ lub zmniejsz zakres ruchu warstwy podczas przesuwania kursora myszy lub przechylania urządzenia mobilnego. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_f1a42bd417390fc63b030a519624607a'] = 'Obrót'; // Rotation
$_MODULE['<{layerslider}prestashop>_331ee65576c7333ba77a13d691219105'] = 'Zwiększ lub zmniejsz zakres obrotu warstwy w przestrzeni 3D podczas przesuwania kursora myszy lub przechylania urządzenia mobilnego. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_a80420eef88d11f77532f1b9cb467fa3'] = 'Perspektywa'; // Perspective
$_MODULE['<{layerslider}prestashop>_7ba7448042bdf18c7669bec909a0a7be'] = 'Zmienia perspektywę warstw w przestrzeni 3D. Jest to wartość domyślna na tym slajdzie, którą odziedziczą warstwy paralaksy, chyba że ustawisz inaczej bezpośrednio na nich.'; // Changes the perspective of layers in the 3D space. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_d6432a4413208eee54d613ceb82f726a'] = 'Filtruj od'; // Filter From
$_MODULE['<{layerslider}prestashop>_bd3ec381eecf6eb78c9a97594745d33c'] = 'Filtry zapewniają efekty takie jak rozmycie lub zmiana koloru warstw. Kliknij w pole tekstowe, aby zobaczyć wybór filtrów, których możesz użyć. Chociaż kliknięcie na predefiniowane opcje zresetuje pole tekstowe, możesz zastosować wiele filtrów, podając po prostu listę wszystkich filtrów, których chcesz użyć, oddzielonych spacją.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use.
$_MODULE['<{layerslider}prestashop>_6b770358764a885d6dc7f2be20604356'] = 'Filtruj do'; // Filter To
$_MODULE['<{layerslider}prestashop>_05b1dc77590105a18fc4c02526fe0c7a'] = 'Autoodtwarzanie'; // Autoplay
$_MODULE['<{layerslider}prestashop>_2b3de50de6ab7bd0aaf46ae654032790'] = 'Pokaż informacje'; // Show Info
$_MODULE['<{layerslider}prestashop>_24b6472fcfa59cddd3f7bbc326582b5f'] = 'Kontrolki'; // Controls
$_MODULE['<{layerslider}prestashop>_58bccbc47e6de6783fb90fd62890a171'] = 'Tryb wypełnienia'; // Fill mode
$_MODULE['<{layerslider}prestashop>_bd7a9717d29c5ddcab1bc175eda1e298'] = 'Głośność'; // Volume
$_MODULE['<{layerslider}prestashop>_56a7f02a3b02e4a16864670ff48745e1'] = 'Użyj tego filmu jako tła slajdu'; // Use this video as slide background
$_MODULE['<{layerslider}prestashop>_4ee3787bc7df95d25272524868e60d4d'] = 'Wymusza na tej warstwie działanie jak tło slajdu, pokrywając cały suwak i ignorując niektóre przejścia. Pamiętaj, aby dostarczyć własny obraz plakatu za pomocą powyższej opcji, aby suwak mógł go natychmiast wyświetlić po załadowaniu strony.'; // Forces this layer to act like the slide background by covering the whole slider and ignoring some transitions. Please make sure to provide your own poster image with the option above, so the slider can display it immediately on page load.
$_MODULE['<{layerslider}prestashop>_9d16dd63ee0afa947dc998fb3d5a4a96'] = 'Wybierz obraz nakładki:'; // Choose an overlay image:
$_MODULE['<{layerslider}prestashop>_e13b4cc51565c9030f943e31c253c8aa'] = 'Pokryj swoje filmy obrazem nakładki, aby uzyskać na nich efekty kropkowane lub w paski.'; // Cover your videos with an overlay image to have dotted or striped effects on them.
$_MODULE['<{layerslider}prestashop>_1529fb44e04df26ff7666faa9f58c605'] = 'Przesunięcie X'; // OffsetX
$_MODULE['<{layerslider}prestashop>_0d12fb40782d7877c5018ff4b501e701'] = 'Przesuwa początkową pozycję warstwy od jej oryginału na osi poziomej o podaną liczbę pikseli. Użyj wartości ujemnych dla przeciwnego kierunku. Wartości procentowe są względne do szerokości tej warstwy. Wartości „lewo” lub „prawo” pozycjonują warstwę poza obszarem roboczym, dzięki czemu wchodzi ona na scenę z dowolnej strony podczas animacji do miejsca docelowego.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it enters the scene from either side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_1508a7d829d65cf5e117fdc2aca0f155'] = 'Przesunięcie Y'; // OffsetY
$_MODULE['<{layerslider}prestashop>_c91f704c049f7d06fe50106d7452c21c'] = 'Przesuwa początkową pozycję warstwy od jej oryginału na osi pionowej o podaną liczbę pikseli. Użyj wartości ujemnych dla przeciwnego kierunku. Wartości procentowe są względne do wysokości tej warstwy. Wartości „góra” lub „dół” pozycjonują warstwę poza obszarem roboczym, dzięki czemu wchodzi ona na scenę z dowolnej strony pionowej podczas animacji do miejsca docelowego.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it enters the scene from either vertical side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_7686cf30c00c9f146a9224a33ba99a0f'] = 'Długość przejścia w milisekundach, gdy warstwa pojawia się na scenie. Sekunda to 1000 milisekund.'; // The length of the transition in milliseconds when the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_f2572c86c0aff2b2b7a92fbb6dee1491'] = 'Rozpocznij o'; // Start at
$_MODULE['<{layerslider}prestashop>_1f413844a6a15351c7a32a16ce962bfd'] = 'Opóźnia przejście o podaną liczbę milisekund, zanim warstwa pojawi się na scenie. Sekunda to 1000 milisekund.'; // Delays the transition with the given amount of milliseconds before the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_32485d52ad7aea25b3bc80d416e76a3b'] = 'Wygładzanie'; // Easing
$_MODULE['<{layerslider}prestashop>_ca9a3cf0ea2e65cd611fe23633cd1186'] = 'Funkcja czasowa animacji. Za pomocą tej funkcji można manipulować ruchem animowanego obiektu. Kliknij link obok tego pola wyboru, aby otworzyć easings.net w celu uzyskania dodatkowych informacji i przykładów w czasie rzeczywistym.'; // The timing function of the animation. With this function you can manipulate the movement of the animated object. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_04e0385c10aefee8e4681617d2f3ef40'] = 'Zanikanie'; // Fade
$_MODULE['<{layerslider}prestashop>_ecdc93d174113fe69b7cbf2c42b5a1cb'] = 'Zanikaj warstwę podczas przejścia.'; // Fade the layer during the transition.
$_MODULE['<{layerslider}prestashop>_b98c4145f7f66383ce71bf31bc4850b2'] = 'Obraca warstwę o podaną liczbę stopni. Wartości ujemne są dozwolone dla obrotu w kierunku przeciwnym do ruchu wskazówek zegara.'; // Rotates the layer by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_801e0dd823542f625e0f2ee135efb62d'] = 'Obrót X'; // RotateX
$_MODULE['<{layerslider}prestashop>_54f64742da0d7bd157ccaf54d4ac73a1'] = 'Obraca warstwę wzdłuż osi X (poziomej) o podaną liczbę stopni. Wartości ujemne są dozwolone dla odwrotnego kierunku.'; // Rotates the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_ea0928ab345567847020e1544892fba0'] = 'Obrót Y'; // RotateY
$_MODULE['<{layerslider}prestashop>_209eea8f9d8a60293098e07e8951e156'] = 'Obraca warstwę wzdłuż osi Y (pionowej) o podaną liczbę stopni. Wartości ujemne są dozwolone dla odwrotnego kierunku.'; // Rotates the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_5a013b463ee01be2924568775fdddfb1'] = 'Pochylenie X'; // SkewX
$_MODULE['<{layerslider}prestashop>_253108f96bfad9912bb2178a4c7aef73'] = 'Pochyla warstwę wzdłuż osi X (poziomej) o podaną liczbę stopni. Wartości ujemne są dozwolone dla odwrotnego kierunku.'; // Skews the layer along the X (horizontal) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_eeb66258f8bf4bb3c0763461b5c1797d'] = 'Pochylenie Y'; // SkewY
$_MODULE['<{layerslider}prestashop>_9d19b1698a8b2f7b0efa8c91067053dd'] = 'Pochyla warstwę wzdłuż osi Y (pionowej) o podaną liczbę stopni. Wartości ujemne są dozwolone dla odwrotnego kierunku.'; // Skews the layer along the Y (vertical) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_b5e0c179725e7f282ffb8e6a96797b49'] = 'Skala X'; // ScaleX
$_MODULE['<{layerslider}prestashop>_15cfa2ea26e51b8489ace013f1b2ec5c'] = 'Skaluje warstwę wzdłuż osi X (poziomej) o podany wektor. Użyj wartości 1 dla oryginalnego rozmiaru. Wartość 2 podwoi, a 0.5 zmniejszy warstwę w porównaniu do jej oryginalnego rozmiaru.'; // Scales the layer along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_3475b72c6483a5c871d245e2567c96c7'] = 'Skala Y'; // ScaleY
$_MODULE['<{layerslider}prestashop>_3db72901337b8e6eeaa04ffd8db52e5e'] = 'Skaluje warstwę wzdłuż osi Y (pionowej) o podany wektor. Użyj wartości 1 dla oryginalnego rozmiaru. Wartość 2 podwoi, a 0.5 zmniejszy warstwę w porównaniu do jej oryginalnego rozmiaru.'; // Scales the layer along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_e55d5d854ca64aed330e5591b62ae112'] = 'Ustawia punkt na płótnie, od którego obliczane są transformacje. Na przykład warstwa może obracać się wokół swojego środka lub całkowicie niestandardowego punktu, takiego jak jeden z jej rogów. Trzy wartości reprezentują osie X, Y i Z w przestrzeni 3D. Oprócz wartości w pikselach i procentach, można również użyć następujących stałych: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.
$_MODULE['<{layerslider}prestashop>_4a18312b5b75f549d5551e5912ad6ebf'] = 'Maska'; // Mask
$_MODULE['<{layerslider}prestashop>_7fb23cb4a33cca7e266b2deda0034711'] = 'Przycinanie (odcinanie) boków warstwy o podaną wartość w pikselach lub procentach. 4 wartości w kolejności: góra, prawo, dół i lewa strona warstwy.'; // Clips (cuts off) the sides of the layer by the given amount specified in pixels or percentages. The 4 value in order: top, right, bottom and the left side of the layer.
$_MODULE['<{layerslider}prestashop>_a9ded1e5ce5d75814730bb4caaf49419'] = 'Tło'; // Background
$_MODULE['<{layerslider}prestashop>_57315a787bf5df775dcdb38f85aacf7b'] = 'Kolor tła Twojej warstwy. Możesz używać nazw kolorów, wartości szesnastkowych, RGB lub RGBA, a także słowa kluczowego „transparent”. Przykład: #FFF'; // The background color of your layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_cdb3e9cc0b2932a6d1543d19732761f1'] = 'Kolor Twojego tekstu. Możesz używać nazw kolorów, wartości szesnastkowych, RGB lub RGBA. Przykład: #333'; // The color of your text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_cabcfc0f365f0e649cf8c229bf54605e'] = 'Zaokrąglone rogi'; // Rounded Corners
$_MODULE['<{layerslider}prestashop>_f0d205bfae354c2e65725ed59bc101e7'] = 'Jeśli chcesz mieć zaokrąglone rogi, możesz ustawić ich promień tutaj w pikselach. Przykład: 5px'; // If you want rounded corners, you can set its radius here in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_32954654ac8fe66a1d09be19001de2d4'] = 'Szerokość'; // Width
$_MODULE['<{layerslider}prestashop>_de11d49b6bbf1b1ecd2b424dc1c0c74a'] = 'Początkowa szerokość tej warstwy, z której będzie animowana do właściwego rozmiaru podczas przejścia.'; // The initial width of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_eec6c4bdbd339edf8cbea68becb85244'] = 'Wysokość'; // Height
$_MODULE['<{layerslider}prestashop>_4cc10791b724542e8a9a04636995d1f5'] = 'Początkowa wysokość tej warstwy, z której będzie animowana do właściwego rozmiaru podczas przejścia.'; // The initial height of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_d7778d0c64b6ba21494c97f77a66885a'] = 'Filtr'; // Filter
$_MODULE['<{layerslider}prestashop>_3f6230752680291a660faeec55dc0b73'] = 'Filtry zapewniają efekty takie jak rozmycie lub zmiana koloru warstw. Kliknij w pole tekstowe, aby zobaczyć wybór filtrów, których możesz użyć. Chociaż kliknięcie na predefiniowane opcje zresetuje pole tekstowe, możesz zastosować wiele filtrów, podając po prostu listę wszystkich filtrów, których chcesz użyć, oddzielonych spacją. Kliknij link „Filtr”, aby uzyskać więcej informacji.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use. Click on the "Filter" link for more information.
$_MODULE['<{layerslider}prestashop>_8cb8ac2653a6471f6779aa5c2d9cded2'] = 'Zmienia perspektywę tej warstwy w przestrzeni 3D.'; // Changes the perspective of this layer in the 3D space.
$_MODULE['<{layerslider}prestashop>_cb1fa274044590e8c05e0e3fe44dd203'] = 'Przesuwa warstwę od jej pierwotnej pozycji na osi poziomej o podaną liczbę pikseli. Użyj wartości ujemnych dla przeciwnego kierunku. Wartości procentowe są względne do szerokości tej warstwy. Wartości „lewo” lub „prawo” animują warstwę poza obszarem roboczym, dzięki czemu może opuścić scenę z dowolnej strony.'; // Shifts the layer from its original position on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' animate the layer out the staging area, so it can leave the scene on either side.
$_MODULE['<{layerslider}prestashop>_aa243196666cd7d2c5e92dd0f8b9b5f4'] = 'Przesuwa warstwę od jej pierwotnej pozycji na osi pionowej o podaną liczbę pikseli. Użyj wartości ujemnych dla przeciwnego kierunku. Wartości procentowe są względne do wysokości tej warstwy. Wartości „góra” lub „dół” animują warstwę poza obszarem roboczym, dzięki czemu może opuścić scenę z dowolnej strony pionowej.'; // Shifts the layer from its original position on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' animate the layer out the staging area, so it can leave the scene on either vertical side.
$_MODULE['<{layerslider}prestashop>_f04f3b646758fcab3a12facb6373fdc0'] = 'Długość przejścia w milisekundach, gdy warstwa opuszcza slajd. Sekunda to 1000 milisekund.'; // The length of the transition in milliseconds when the layer leaves the slide. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_b92bb5e60806c72def5363a5a8bb035e'] = 'Możesz ustawić czas rozpoczęcia tego przejścia. Użyj jednej z predefiniowanych opcji, aby użyć czasu względnego, który można przesunąć za pomocą niestandardowych operacji.'; // You can set the starting time of this transition. Use one of the pre-defined options to use relative timing, which can be shifted with custom operations.
$_MODULE['<{layerslider}prestashop>_c36ace66cf4777473ba3200cf815253c'] = 'Rozpoczyna się zmiana slajdu (ignorując modyfikator)'; // Slide change starts (ignoring modifier)
$_MODULE['<{layerslider}prestashop>_371b285fa971d884eaebf156db4065c8'] = 'Zakończenie przejścia otwierającego'; // Opening Transition completes
$_MODULE['<{layerslider}prestashop>_8920002666c88ed85ae80665159154f4'] = 'Rozpoczęcie przejścia tekstu otwierającego'; // Opening Text Transition starts
$_MODULE['<{layerslider}prestashop>_284f03773b79e8472a3798c95c4b9f63'] = 'Zakończenie przejścia tekstu otwierającego'; // Opening Text Transition completes
$_MODULE['<{layerslider}prestashop>_9131e07bbb8c30dd60ba3ccb9fdd90a4'] = 'Zakończenie przejścia otwierającego i przejścia tekstu otwierającego'; // Opening and Opening Text Transition complete
$_MODULE['<{layerslider}prestashop>_02a208641e1ff3dd5c51825491cce356'] = 'Rozpoczęcie pętli'; // Loop starts
