$_MODULE['<{layerslider}prestashop>_3fff50b68e60ed555ff901b0fdfcd783'] = 'Przesuwa początkową pozycję węzłów tekstowych od ich oryginału na osi poziomej o podaną liczbę pikseli. Użyj wartości ujemnych dla przeciwnego kierunku. Wartości procentowe są względne do szerokości tej warstwy. Wartości „lewo” lub „prawo” pozycjonują węzły tekstowe poza obszarem roboczym, dzięki czemu wchodzą one na scenę z dowolnej strony podczas animacji do miejsca docelowego. Wymieniając wiele wartości oddzielonych znakiem |, suwak użyje różnych wariantów przejścia dla każdego węzła tekstowego, cyklicznie przechodząc przez podane wartości.'; // Shifts the starting position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they enter the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_e1d2fdcc944aa0f2e839f171f044d659'] = 'Przesuwa początkową pozycję węzłów tekstowych od ich oryginału na osi pionowej o podaną liczbę pikseli. Użyj wartości ujemnych dla przeciwnego kierunku. Wartości procentowe są względne do szerokości tej warstwy. Wartości „góra” lub „dół” pozycjonują węzły tekstowe poza obszarem roboczym, dzięki czemu wchodzą one na scenę z dowolnej strony pionowej podczas animacji do miejsca docelowego. Wymieniając wiele wartości oddzielonych znakiem |, suwak użyje różnych wariantów przejścia dla każdego węzła tekstowego, cyklicznie przechodząc przez podane wartości.'; // Shifts the starting position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they enter the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_968c58d8f1922a6b84d393c59a64a49c'] = 'Długość przejścia poszczególnych fragmentów tekstu w milisekundach. Sekunda to 1000 milisekund.'; // The transition length in milliseconds of the individual text fragments. A second equals to 1000 milliseconds.
