$_MODULE['<{layerslider}prestashop>_fff3063495dd33cf3909fa4b1a9bc98d'] = 'Obraca fragmenty tekstu zgodnie z ruchem wskazówek zegara o podaną liczbę stopni. Wartości ujemne są dozwolone dla obrotu w kierunku przeciwnym do ruchu wskazówek zegara. Wymieniając wiele wartości oddzielonych znakiem |, suwak użyje różnych wariantów przejścia dla każdego węzła tekstowego, cyklicznie przechodząc przez podane wartości.'; // Rotates text fragments clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_14f1aa4b97984dfcc375079b84f0eccc'] = 'Obraca fragmenty tekstu wzdłuż osi X (poziomej) o podaną liczbę stopni. Wartości ujemne są dozwolone dla odwrotnego kierunku. Wymieniając wiele wartości oddzielonych znakiem |, suwak użyje różnych wariantów przejścia dla każdego węzła tekstowego, cyklicznie przechodząc przez podane wartości.'; // Rotates text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
