$_MODULE['<{layerslider}prestashop>_fd776f8e6385f4f4e57c79701beb1f12'] = 'Skaluje fragmenty tekstu wzdłuż osi X (poziomej) o podany wektor. Użyj wartości 1 dla oryginalnego rozmiaru. Wartość 2 podwoi, a 0.5 zmniejszy fragmenty tekstu w porównaniu do ich oryginalnego rozmiaru. Wymieniając wiele wartości oddzielonych znakiem |, suwak użyje różnych wariantów przejścia dla każdego węzła tekstowego, cyklicznie przechodząc przez podane wartości.'; // Scales text fragments along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_b95364eee0d39f1ff08c9511fd007c3b'] = 'Skaluje fragmenty tekstu wzdłuż osi Y (pionowej) o podany wektor. Użyj wartości 1 dla oryginalnego rozmiaru. Wartość 2 podwoi, a 0.5 zmniejszy fragmenty tekstu w porównaniu do ich oryginalnego rozmiaru. Wymieniając wiele wartości oddzielonych znakiem |, suwak użyje różnych wariantów przejścia dla każdego węzła tekstowego, cyklicznie przechodząc przez podane wartości.'; // Scales text fragments along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
