$_MODULE['<{layerslider}prestashop>_0c6a5ad5f832c1f79c4b4d62fee16e26'] = 'Kąt obrotu na osi pionowej, do którego animuje się ta warstwa podczas wchodzenia na obszar suwaka. Wartości ujemne są dozwolone dla odwrotnego kierunku.'; // The rotation angle on the vertical axis where this layer animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_6af83f149c018cdec1dba351c619b7ca'] = 'Skala pozioma warstwy, do której animuje się ta warstwa podczas wchodzenia na obszar suwaka.'; // The layer horizontal scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_28d8b2ec189dc2eb778a851265cf4f26'] = 'Skala pionowa warstwy, do której animuje się ta warstwa podczas wchodzenia na obszar suwaka.'; // The layer vertical scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_63d48e08093f6964b3cdc6d33740663e'] = 'Kąt pochylenia poziomego warstwy, do którego animuje się ta warstwa podczas wchodzenia na obszar suwaka.'; // The layer horizontal skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_e4b23d4080824b973029720a307cbae6'] = 'Kąt pochylenia pionowego warstwy, do którego animuje się ta warstwa podczas wchodzenia na obszar suwaka.'; // The layer vertical skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_45f908bb74a7835d23630c7d51031fed'] = 'Oblicz pozycje od'; // Calculate positions from
$_MODULE['<{layerslider}prestashop>_639b76980c25ea95700d2c2e96833964'] = 'Ustawia początek pozycji warstwy, od którego obliczane są wartości górne i lewe. Domyślnie jest to lewy górny róg obszaru suwaka. W suwaku o pełnej szerokości i pełnym rozmiarze zawartość jest wyśrodkowana na podstawie rozmiaru ekranu, aby uzyskać jak najlepsze dopasowanie. Wybierając opcję „boki ekranu” w tych scenariuszach, można pozwolić warstwom na ucieczkę z wyśrodkowanego obszaru wewnętrznego i przyklejenie się do boków ekranu.'; // Sets the layer position origin from which top and left values are calculated. The default is the upper left corner of the slider canvas. In a full width and full size slider, your content is centered based on the screen size to achieve the best possible fit. By selecting the "sides of the screen" option in those scenarios, you can allow layers to escape the centered inner area and stick to the sides of the screen.
$_MODULE['<{layerslider}prestashop>_b16710c8d62abca1ccda544c63bea7e8'] = 'boki suwaka'; // sides of the slider
$_MODULE['<{layerslider}prestashop>_ab761fc53dc83dca5a36b9a25bf548bf'] = 'boki ekranu'; // sides of the screen
$_MODULE['<{layerslider}prestashop>_51400b417ad07f539ecfd9469027a5b6'] = 'Kolejność nakładania'; // Stacking order
$_MODULE['<{layerslider}prestashop>_4c26a68fa7463987e86f61733caf8491'] = 'Ta opcja kontroluje pionową kolejność nakładania się warstw, które się pokrywają. W CSS jest to powszechnie nazywane z-index. Elementy o wyższej wartości są umieszczane przed elementami o niższej wartości, skutecznie je zakrywając. Domyślnie wartość ta jest obliczana automatycznie na podstawie kolejności warstw, więc proste ich przeorganizowanie może rozwiązać problemy z nakładaniem się. Używaj tej opcji tylko wtedy, gdy chcesz ręcznie ustawić własną wartość w szczególnych przypadkach, takich jak używanie warstw statycznych.<br><br>Na każdym slajdzie kolejność nakładania zaczyna się od 100. Podanie liczby mniejszej niż 100 umieści warstwę za wszystkimi innymi warstwami na wszystkich slajdach. Podanie znacznie większej liczby, na przykład 500, sprawi, że warstwa będzie na wierzchu wszystkiego.'; // This option controls the vertical stacking order of layers that overlap. In CSS, it's commonly called as z-index. Elements with a higher value are stacked in front of elements with a lower one, effectively covering them. By default, this value is calculated automatically based on the order of your layers, thus simply re-ordering them can fix overlap issues. Use this option only if you want to set your own value manually in special cases like using static layers.<br><br>On each slide, the stacking order starts counting from 100. Providing a number less than 100 will put the layer behind every other layer on all slides. Specifying a much greater number, for example 500, will make the layer to be on top of everything else.
$_MODULE['<{layerslider}prestashop>_0c301043ef92f5854d711e54f96a86c5'] = 'Tryb mieszania'; // Blend mode
$_MODULE['<{layerslider}prestashop>_df5c4d0c2cd9156afa20fa59c572acde'] = 'Wybierz, w jaki sposób warstwy i tło slajdu mają się ze sobą mieszać. Tryby mieszania to łatwy sposób na dodanie efektownych efektów i jest jedną z najczęściej używanych funkcji w projektowaniu graficznym i druku.'; // Choose how layers and the slide background should blend into each other. Blend modes are an easy way to add eye-catching effects and is one of the most frequently used features in graphic and print design.
$_MODULE['<{layerslider}prestashop>_b718adec73e04ce3ec720dd11a06a308'] = 'ID'; // ID
$_MODULE['<{layerslider}prestashop>_ca79528715d6c07cb429e8189105cbb4'] = 'Możesz zastosować atrybut ID na elemencie HTML tej warstwy, aby pracować z nim w niestandardowym kodzie CSS lub Javascript.'; // You can apply an ID attribute on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_e9878b4854d29907146149f695cb1cfb'] = 'Klasy'; // Classes
$_MODULE['<{layerslider}prestashop>_c666f7b19a598af3cadb8c9cb07c4bcd'] = 'Możesz zastosować klasy na elemencie HTML tej warstwy, aby pracować z nim w niestandardowym kodzie CSS lub Javascript.'; // You can apply classes on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_3ace045d5becea8953aabde365c5c8d8'] = 'Możesz dodać tytuł do tej warstwy, który będzie wyświetlany jako podpowiedź, jeśli ktoś przytrzyma kursor myszy nad warstwą.'; // You can add a title to this layer which will display as a tooltip if someone holds his mouse cursor over the layer.
$_MODULE['<{layerslider}prestashop>_f2364c335fe8ae15c8d64b2744db0f40'] = 'Nazwij lub opisz warstwę obrazu, aby wyszukiwarki i oprogramowanie VoiceOver mogły go prawidłowo zidentyfikować.'; // Name or describe your image layer, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_eba991d56b1be0b940d722211bab87bc'] = 'Rel'; // Rel
$_MODULE['<{layerslider}prestashop>_b987cf5b1aa6af2a92b97f69d65c29df'] = 'Wtyczki i wyszukiwarki mogą używać tego atrybutu, aby uzyskać więcej informacji o roli i zachowaniu linku.'; // Plugins and search engines may use this attribute to get more information about the role and behavior of a link.
$_MODULE['<{layerslider}prestashop>_5d083603a18046659c2b4b23af7948cc'] = 'Opcja zaawansowana'; // Advanced option
$_MODULE['<{layerslider}prestashop>_31fde7b05ac8952dacf4af8a704074ec'] = 'Podgląd'; // Preview
