$_MODULE['<{layerslider}prestashop>_35b93b52adc0893d6f4b32752660535f'] = '<i>liczba</i> lub <i>min,max</i> Jeśli podasz wartość większą niż 1, Creative Slider podzieli Twój slajd na kafelki. Możesz tutaj określić, ile wierszy ma mieć Twoje przejście. Jeśli podasz dwie liczby oddzielone przecinkiem, Creative Slider użyje tego jako zakresu i wybierze losową liczbę z Twoich wartości.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many rows of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_d27561f45c58f407b3fe76b63b1ec28a'] = 'Kol.'; // Cols
$_MODULE['<{layerslider}prestashop>_a122bf49cbf8c9cf02971a495e81ed16'] = '<i>liczba</i> lub <i>min,max</i> Jeśli podasz wartość większą niż 1, Creative Slider podzieli Twój slajd na kafelki. Możesz tutaj określić, ile kolumn ma mieć Twoje przejście. Jeśli podasz dwie liczby oddzielone przecinkiem, Creative Slider użyje tego jako zakresu i wybierze losową liczbę z Twoich wartości.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many columns of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_8f497c1a3d15af9e0c215019f26b887d'] = 'Opóźnienie'; // Delay
$_MODULE['<{layerslider}prestashop>_d4f0208d1a34d7a381fc8abec990105b'] = 'Możesz zastosować opóźnienie między kafelkami i odłożyć ich animację względem siebie.'; // You can apply a delay between the tiles and postpone their animation relative to each other.
$_MODULE['<{layerslider}prestashop>_3ff39d3acb327553070a64ef0cb321d5'] = 'Sekwencja'; // Sequence
$_MODULE['<{layerslider}prestashop>_434cd8b268e79b39af562cc6329d56fb'] = 'Możesz tutaj kontrolować kolejność animacji kafelków.'; // You can control the animation order of the tiles here.
