$_MODULE['<{layerslider}prestashop>_8ff332ee12d145447fdba276df907268'] = 'Skrypt próbuje zidentyfikować optymalną głębokość dla obracanych obiektów (kafelków). Za pomocą tej opcji można wymusić na obiektach dużą głębokość podczas wykonywania obrotu o 180 stopni (i jego wielokrotności).'; // The script tries to identify the optimal depth for your rotated objects (tiles). With this option you can force your objects to have a large depth when performing 180 degree (and its multiplies) rotation.
$_MODULE['<{layerslider}prestashop>_4aaea893e82ee53fc4aab0eae485be41'] = 'Duża głębokość'; // Large depth
