$_MODULE['<{layerslider}prestashop>_434108995bd42e16e902e952b137e772'] = 'To najczęściej używana metoda. Wystarczy wybrać hook z listy, a pojawi się on w Twoim front-office. (Można to również dostosować w zakładce Ustawienia suwaka / Układ.)'; // This is the most commonly used method. Just select a hook from the list, and it will appear on your frontoffice. (This can be also adjusted in the Slider Settings / Layout tab.)
$_MODULE['<{layerslider}prestashop>_7d02e750a82330b9e55931e60438bd25'] = 'W zakładce Ustawienia suwaka / Różne możesz również zdefiniować, na których stronach i kategoriach będzie się on pojawiał. Dostępne są również dodatkowe filtry, takie jak Sklep i Język.'; // In Slider Settings / Misc tab you can also define on which Pages and Categories will it appear. There are additional filters like Shop and Language as well.
$_MODULE['<{layerslider}prestashop>_a04a8217af417bf7fc2e7e0bad698b35'] = 'Alternatywna metoda: Shortcode'; // Alternate Method: Shortcode
$_MODULE['<{layerslider}prestashop>_8554b8e3467a0f1c0d0e0d0887a708a6'] = 'Shortcody można wstawiać do treści, takich jak strona CMS, opis kategorii lub produktu. Może to pomóc umieścić suwak w odpowiednim miejscu, nawet jeśli nie ma tam dostępnego hooka. Użycie jest dość proste, wystarczy umieścić shortcode w edytorze treści, gdzie numer to ID suwaka (można również użyć tam slugu, jeśli został on ustawiony w ustawieniach suwaka).'; // Shortcodes can be inserted into content, like CMS page, category or product description. This can help you to place a slider into a suitable area, even if there is no available hook there. To use that is quite easy, just need to place the shortcode into the content editor, where number is the ID of the slider (you can also use slug there if you set that in the slider settings).
